// Package worker holds the River jobs of the identity module.
package worker

import (
	"context"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/riverqueue/river"

	"github.com/lhbotero1985/booking-platform-backend/internal/platform/jobs"
)

// SendVerificationEmailArgs schedules a verification email. It carries only the user ID: the
// token is generated by the worker at send time so it is never stored in the job queue.
type SendVerificationEmailArgs struct {
	UserID uuid.UUID `json:"user_id"`
}

// Kind implements river.JobArgs.
func (SendVerificationEmailArgs) Kind() string { return "identity.send_verification_email" }

// InsertOpts implements river.JobArgsWithInsertOpts. Requests for the same user within one
// minute are coalesced (throttles "resend verification").
func (SendVerificationEmailArgs) InsertOpts() river.InsertOpts {
	return river.InsertOpts{
		Queue:       jobs.QueueNotifications,
		MaxAttempts: 8,
		UniqueOpts:  river.UniqueOpts{ByArgs: true, ByPeriod: time.Minute},
	}
}

// VerificationSender is the use case the worker invokes.
type VerificationSender interface {
	SendVerificationEmail(ctx context.Context, userID uuid.UUID) error
}

// SendVerificationEmailWorker runs SendVerificationEmailArgs jobs.
type SendVerificationEmailWorker struct {
	river.WorkerDefaults[SendVerificationEmailArgs]
	sender VerificationSender
}

// Work implements river.Worker.
func (w *SendVerificationEmailWorker) Work(ctx context.Context, job *river.Job[SendVerificationEmailArgs]) error {
	return w.sender.SendVerificationEmail(ctx, job.Args.UserID)
}

// Timeout bounds one delivery attempt (SMTP included).
func (w *SendVerificationEmailWorker) Timeout(*river.Job[SendVerificationEmailArgs]) time.Duration {
	return 30 * time.Second
}

// Register adds the identity workers to workers.
func Register(workers *river.Workers, sender VerificationSender) error {
	if err := river.AddWorkerSafely(workers, &SendVerificationEmailWorker{sender: sender}); err != nil {
		return fmt.Errorf("identity worker: %w", err)
	}
	return nil
}
